    const y3=Math.max(yb+.06,Math.min(.62,sh-.14)),y2=Math.max(yb+.03,Math.min(.40,y3-.10)),y4=Math.max(y3+.02,sh),y5=Math.max(y4+.02,yB(z));
    const s=[[0,yb],[xw-.10,yb],[xw-.02,y2],[xw,y3],[xw-.015,y4],[xw-.075,y5]];
