    bulleOutils.tube(P,'c',[[sd*.30,.36,LF+.02],[sd*.46,.36,LF+.02],[sd*.545,.36,LF+.008]].concat([2.16,2.13,2.10,2.06].map(z=>[sd*(xW(z)+.006),.36,z])),[[.02,0],[.014,.014],[0,.02],[-.014,.014],[-.02,0],[-.014,-.014],[0,-.02],[.014,-.014]],true);
