    const up=Math.abs(d[1])<.92?[0,1,0]:[1,0,0];
    let e1=[up[1]*d[2]-up[2]*d[1],up[2]*d[0]-up[0]*d[2],up[0]*d[1]-up[1]*d[0]];const m1=Math.hypot(e1[0],e1[1],e1[2]);e1=[e1[0]/m1,e1[1]/m1,e1[2]/m1];
