  const LW=.12,OFF=.012,onB=(z,t)=>{const p=surf(3,z,t),[nn]=nrm(3,z,t);return [p[0]+nn[0]*OFF,p[1]+nn[1]*OFF,p[2]+nn[2]*OFF];};
