    // LA BULLE : une seule place, glace sombre, posée sur le fuselage
    const cwB=z=>U.lin([[-.45,.02],[-.1,.27],[.5,.31],[1.0,.22],[1.3,.02]],z),ctB=z=>U.lin([[-.45,.74],[.1,1.03],[.55,1.07],[1.0,.93],[1.3,.70]],z);
