  J.lathe('d',[[R*.26,fx-.004],[R*.10,fx-.004]],16,0,0,0,'x');                                 // le voile du moyeu : entre les branches, on voit le disque et l'étrier
  J.lathe('b',[[R*.56,fx-.05],[R*.26,fx-.05]],20,0,0,0,'x');                                   // le disque de frein
